import os
import zipfile
import io
from flask import Flask, request, send_file, jsonify

app = Flask(__name__)

@app.route('/convert', methods=['POST'])
def convert():
    if 'file' not in request.files:
        return jsonify({"error": "No file part in the request"}), 400

    uploaded_file = request.files['file']

    if uploaded_file.filename == '':
        return jsonify({"error": "No file selected for uploading"}), 400

    if not uploaded_file.filename.endswith('.zip'):
        return jsonify({"error": "Only .zip files are allowed"}), 400

    try:
        zip_stream = io.BytesIO(uploaded_file.read())
        text_parts = []

        with zipfile.ZipFile(zip_stream, 'r') as zf:
            for member in zf.namelist():
                if member.endswith('.txt') or member.endswith('.py') or member.endswith('.js') or member.endswith('.ts') or member.endswith('.html') or member.endswith('.css') or member.endswith('.json') or member.endswith('.csv') or member.endswith('.md'):
                    try:
                        content = zf.read(member).decode('utf-8')
                        text_parts.append(content)
                    except Exception:
                        continue

        if not text_parts:
            return "No text files found in the zip archive.", 400

        combined_text = "\n".join(text_parts)

        return combined_text, 200, {'Content-Type': 'text/plain'}

    except zipfile.BadZipFile:
        return jsonify({"error": "Invalid zip file"}), 400
    except Exception as e:
        return jsonify({"error": str(e)}), 500

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=5000)
